"""Streaming statistics primitives (pure Python, stdlib only).

TODO(project): percentile() and the covariance/correlation accumulator are
stubs — implement them per the project brief.
"""

from math import sqrt


class StreamingStats:
    """Online mean/variance via Welford's algorithm — O(1) memory per update."""

    def __init__(self) -> None:
        self._n = 0
        self._mean = 0.0
        self._m2 = 0.0
        self._min = float("inf")
        self._max = float("-inf")

    def add(self, x: float) -> None:
        self._n += 1
        delta = x - self._mean
        self._mean += delta / self._n
        self._m2 += delta * (x - self._mean)
        if x < self._min:
            self._min = x
        if x > self._max:
            self._max = x

    @property
    def n(self) -> int:
        return self._n

    @property
    def mean(self) -> float:
        if self._n == 0:
            raise ValueError("no observations yet")
        return self._mean

    @property
    def variance(self) -> float:
        """Sample variance (ddof=1); raises before two observations."""
        if self._n < 2:
            raise ValueError("sample variance needs >= 2 observations")
        return self._m2 / (self._n - 1)

    @property
    def population_variance(self) -> float:
        if self._n == 0:
            raise ValueError("no observations yet")
        return self._m2 / self._n

    @property
    def stddev(self) -> float:
        return sqrt(self.variance)

    @property
    def min(self) -> float:
        if self._n == 0:
            raise ValueError("no observations yet")
        return self._min

    @property
    def max(self) -> float:
        if self._n == 0:
            raise ValueError("no observations yet")
        return self._max


